-- JSON blocks are deliberately readable: tests audit their exact source coverage.
WITH payload AS (SELECT $cubingapp_cs_patch${
  "patches": [
    {
      "name": "Pair / Right 5-1",
      "mode": "replace",
      "algs": [
        [
          {
            "alg": "/ 2,-3 / -1,-2 / -3,0 /",
            "source": "cubingapp"
          }
        ]
      ]
    },
    {
      "name": "Parallel Edges / Left 4-2",
      "mode": "prepend",
      "algs": [
        [
          {
            "alg": "/ 0,-4 / 3,-2 / -1,-2 / 0,-3 /",
            "source": "cubingapp"
          }
        ]
      ]
    },
    {
      "name": "3-2-1 / Parallel Edges",
      "mode": "prepend",
      "algs": [
        [
          {
            "alg": "/ 4,-1 / 2,0 / -1,-2 / -3,-3 /",
            "source": "cubingapp"
          }
        ]
      ]
    },
    {
      "name": "Parallel Edges / 3-2-1",
      "mode": "prepend",
      "algs": [
        [
          {
            "alg": "/ -1,4 / 0,2 / -2,-1 / -3,-3 / -1,1",
            "source": "cubingapp"
          }
        ]
      ]
    },
    {
      "name": "3-1-2 / Parallel Edges",
      "mode": "prepend",
      "algs": [
        [
          {
            "alg": "/ 0,-3 / -3,0 / 2,-3 / -2,-1 / -3,0 / -1,1",
            "source": "cubingapp"
          }
        ]
      ]
    },
    {
      "name": "Parallel Edges / 3-1-2",
      "mode": "prepend",
      "algs": [
        [
          {
            "alg": "/ -3,0 / 0,-3 / -3,2 / -1,-2 / 0,-3 /",
            "source": "cubingapp"
          }
        ]
      ]
    }
  ],
  "missing": {
    "position": 84,
    "name": "Left 4-2 / Perpendicular Edges",
    "subgroup": "5 Slices",
    "setup": "/(3,0)/(1,2)/(2,-3)/(3,-4)/",
    "sticker": {
      "kind": "raw",
      "tag": "sqcube",
      "attrs": {}
    },
    "algs": [
      [
        {
          "alg": "/ -3,4 / -2,3 / -1,-2 / -3,0 /",
          "source": "cubingapp"
        }
      ]
    ]
  }
}$cubingapp_cs_patch$::jsonb AS body),
patches AS (SELECT value AS patch FROM payload, jsonb_array_elements(body->'patches'))
UPDATE alg_cases AS c
SET algs = CASE
  WHEN patches.patch->>'mode' = 'replace' THEN patches.patch->'algs'
  ELSE jsonb_build_array(
    COALESCE(patches.patch->'algs'->0, '[]'::jsonb) ||
    COALESCE((
      SELECT jsonb_agg(existing.entry ORDER BY existing.ord)
      FROM jsonb_array_elements(COALESCE(c.algs->0, '[]'::jsonb)) WITH ORDINALITY AS existing(entry, ord)
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(COALESCE(patches.patch->'algs'->0, '[]'::jsonb)) AS added(entry)
        WHERE added.entry->>'alg' = existing.entry->>'alg'
      )
    ), '[]'::jsonb)
  )
END
FROM patches
WHERE c.puzzle = 'sq1' AND c.set_slug = 'cs' AND c.name = patches.patch->>'name';

